use fsym_core::{BigInt, BigRational, Constant, Expr, RealBall};
use fsym_core::ball::BallError;
use std::str::FromStr;

fn main() {
    for precision in [0, 2001] {
        let refused = matches!(RealBall::pi(precision), Err(BallError::ArgumentOutsideDeclaredEnvelope(_)));
        println!("pi_precision_{precision}_typed_refusal={refused}");
        assert!(refused);
    }
    let huge = BigInt::from_str(&format!("1{}", "0".repeat(1001))).unwrap();
    let refused = matches!(RealBall::exact(BigRational::from_integer(huge)).sin(30), Err(BallError::ArgumentOutsideDeclaredEnvelope(_)));
    println!("sin_10pow1001_typed_refusal={refused}");
    assert!(refused);
    let refused = matches!(RealBall::from_i64(100_000).exp(30), Err(BallError::ArgumentOutsideDeclaredEnvelope(_)));
    println!("exp_100000_typed_refusal={refused}");
    assert!(refused);
    // Exact public-contract check, independent of transcendental oracle accuracy:
    // evalf_ball promises a radius respecting the requested decimal precision.
    let precision = 8;
    let target = BigRational::new(BigInt::from(1), BigInt::from(100_000_000));
    let scale = BigInt::from_str("100000000000000000000000000000000000000000000000000").unwrap();
    let expr = Expr::Mul(vec![Expr::Integer(scale.clone()), Expr::Const(Constant::Pi)]);
    let point = Expr::Const(Constant::Pi).evalf_ball(precision).unwrap();
    let amplified = expr.evalf_ball(precision).unwrap();
    println!("pi_radius_within_requested_target={}", point.radius() <= &target);
    println!("scaled_pi_radius_within_requested_target={}", amplified.radius() <= &target);
    println!("scaled_pi_radius_exceeds_one={}", amplified.radius() > &BigRational::from(1));
    println!("scaled_pi_radius_exactly_child_radius_times_scale={}", amplified.radius() == &(point.radius() * BigRational::from_integer(scale)));
    // Preserve the observed failure as data; this probe is not a passing gate.
    if amplified.radius() > &target {
        println!("NUMERIC_GATE_BLOCKED: accepted composed expression violates requested absolute radius contract");
        std::process::exit(1);
    }
}
